export function tint(hex: string, amount: number): string {
  const num = parseInt(hex.slice(1), 16)
  const r = (num >> 16) & 255
  const g = (num >> 8) & 255
  const b = num & 255
  const tr = Math.round(r + (255 - r) * amount)
  const tg = Math.round(g + (255 - g) * amount)
  const tb = Math.round(b + (255 - b) * amount)
  return `rgb(${tr}, ${tg}, ${tb})`
}

export function withAlpha(hex: string, alpha: number): string {
  const num = parseInt(hex.slice(1), 16)
  const r = (num >> 16) & 255
  const g = (num >> 8) & 255
  const b = num & 255
  return `rgba(${r}, ${g}, ${b}, ${alpha})`
}

import { openDB, type DBSchema, type IDBPDatabase } from "idb"
import type { Habit, MoodEntry, Completion } from "../types"

interface RhythmDB extends DBSchema {
  habits: { key: string; value: Habit }
  completions: { key: string; value: Completion }
  moods: { key: string; value: MoodEntry }
}

let dbPromise: Promise<IDBPDatabase<RhythmDB>> | null = null

export function getDB(): Promise<IDBPDatabase<RhythmDB>> {
  if (!dbPromise) {
    dbPromise = openDB<RhythmDB>("rhythm", 1, {
      upgrade(db) {
        db.createObjectStore("habits", { keyPath: "id" })
        const completions = db.createObjectStore("completions", { keyPath: "key" })
        completions.createIndex("habitId", "habitId")
        db.createObjectStore("moods", { keyPath: "date" })
      },
    })
  }
  return dbPromise
}

function completionKey(habitId: string, date: string): string {
  return `${habitId}::${date}`
}

export async function getHabits(): Promise<Habit[]> {
  const db = await getDB()
  return db.getAll("habits")
}

export async function upsertHabit(habit: Habit): Promise<void> {
  const db = await getDB()
  await db.put("habits", habit)
}

export async function deleteHabit(id: string): Promise<void> {
  const db = await getDB()
  await db.delete("habits", id)
  const completions = await db.getAllFromIndex("completions", "habitId", id)
  for (const c of completions) {
    await db.delete("completions", c.key)
  }
}

export async function completeHabit(habitId: string, date: string): Promise<void> {
  const db = await getDB()
  await db.put("completions", { habitId, date, key: completionKey(habitId, date) })
}

export async function uncompleteHabit(habitId: string, date: string): Promise<void> {
  const db = await getDB()
  await db.delete("completions", completionKey(habitId, date))
}

export async function getCompletions(): Promise<Completion[]> {
  const db = await getDB()
  return db.getAll("completions")
}

export async function getMoods(): Promise<MoodEntry[]> {
  const db = await getDB()
  return db.getAll("moods")
}

export async function saveMood(entry: MoodEntry): Promise<void> {
  const db = await getDB()
  await db.put("moods", entry)
}

export async function clearAll(): Promise<void> {
  const db = await getDB()
  await db.clear("habits")
  await db.clear("completions")
  await db.clear("moods")
}

import { useEffect, useState } from "react"

export type Appearance = "system" | "light" | "dark"

const KEY = "rhythm:appearance"

function readInitial(): Appearance {
  try {
    const stored = window.localStorage.getItem(KEY)
    if (stored === "system" || stored === "light" || stored === "dark") {
      return stored
    }
  } catch {
    /* ignore */
  }
  return "system"
}

function systemIsDark(): boolean {
  return typeof window !== "undefined" && window.matchMedia("(prefers-color-scheme: dark)").matches
}

export function useDarkMode() {
  const [appearance, setAppearanceState] = useState<Appearance>(readInitial)

  function setAppearance(value: Appearance) {
    setAppearanceState(value)
    try {
      window.localStorage.setItem(KEY, value)
    } catch {
      /* ignore */
    }
  }

  useEffect(() => {
    const root = document.documentElement
    const wantsDark =
      appearance === "dark" || (appearance === "system" && systemIsDark())
    root.classList.toggle("dark", wantsDark)
    if (appearance === "light") root.classList.add("light")
    else root.classList.remove("light")
  }, [appearance])

  useEffect(() => {
    if (appearance !== "system") return
    const media = window.matchMedia("(prefers-color-scheme: dark)")
    const handler = () => {
      document.documentElement.classList.toggle("dark", media.matches)
    }
    media.addEventListener("change", handler)
    return () => media.removeEventListener("change", handler)
  }, [appearance])

  return { appearance, setAppearance }
}

import { useEffect, useState } from "react"

export function usePWA() {
  const [prompt, setPrompt] = useState<BeforeInstallPromptEvent | null>(null)

  useEffect(() => {
    function handler(event: Event) {
      event.preventDefault()
      setPrompt(event as unknown as BeforeInstallPromptEvent)
    }
    window.addEventListener("beforeinstallprompt", handler)
    return () => window.removeEventListener("beforeinstallprompt", handler)
  }, [])

  async function install() {
    if (!prompt) return
    prompt.prompt()
    const { outcome } = await prompt.userChoice
    setPrompt(null)
    return outcome
  }

  return { prompt, install }
}

export interface BeforeInstallPromptEvent extends Event {
  prompt: () => void
  userChoice: Promise<{ outcome: "accepted" | "dismissed" }>
}

import { useCallback, useEffect, useState } from "react"
import * as db from "../lib/db"
import { todayKey } from "../lib/date"
import type { Habit, MoodEntry } from "../types"

interface State {
  habits: Habit[]
  completions: Array<{ habitId: string; date: string }>
  moods: MoodEntry[]
  ready: boolean
}

function emptyState(): State {
  return { habits: [], completions: [], moods: [], ready: false }
}

export function useData() {
  const [state, setState] = useState<State>(emptyState())

  const load = useCallback(async () => {
    try {
      const [habits, completions, moods] = await Promise.all([
        db.getHabits(),
        db.getCompletions(),
        db.getMoods(),
      ])
      setState({ habits, completions, moods, ready: true })
    } catch (error) {
      console.error("Rhythm: data load failed", error)
      setState((s) => ({ ...s, ready: true }))
    }
  }, [])

  useEffect(() => {
    load()
  }, [load])

  useEffect(() => {
    function reload() {
      load()
    }
    window.addEventListener("focus", reload)
    document.addEventListener("visibilitychange", reload)
    return () => {
      window.removeEventListener("focus", reload)
      document.removeEventListener("visibilitychange", reload)
    }
  }, [load])

  const toggleHabit = useCallback(
    async (habitId: string, date = todayKey()) => {
      const was = state.completions.some(
        (c) => c.habitId === habitId && c.date === date
      )
      if (was) await db.uncompleteHabit(habitId, date)
      else await db.completeHabit(habitId, date)
      await load()
    },
    [state.completions, load]
  )

  const addHabit = useCallback(
    async (partial: Omit<Habit, "id"> & { id?: string }) => {
      const habit: Habit = {
        ...partial,
        id: partial.id ?? crypto.randomUUID(),
        createdAt: partial.createdAt ?? Date.now(),
      }
      await db.upsertHabit(habit)
      await load()
    },
    [load]
  )

  const renameHabit = useCallback(
    async (id: string, name: string) => {
      const habit = state.habits.find((h) => h.id === id)
      if (!habit) return
      await db.upsertHabit({ ...habit, name })
      await load()
    },
    [state.habits, load]
  )

  const updateHabitStyle = useCallback(
    async (id: string, patch: Partial<Pick<Habit, "emoji" | "color">>) => {
      const habit = state.habits.find((h) => h.id === id)
      if (!habit) return
      await db.upsertHabit({ ...habit, ...patch })
      await load()
    },
    [state.habits, load]
  )

  const deleteHabit = useCallback(
    async (id: string) => {
      await db.deleteHabit(id)
      await load()
    },
    [load]
  )

  const saveMood = useCallback(
    async (value: number, note: string, date = todayKey()) => {
      await db.saveMood({ date, value, note })
      await load()
    },
    [load]
  )

  const clearAll = useCallback(async () => {
    await db.clearAll()
    await load()
  }, [load])

  const completedToday = state.completions
    .filter((c) => c.date === todayKey())
    .map((c) => c.habitId)

  return {
    state,
    ready: state.ready,
    habits: state.habits,
    completions: state.completions,
    moods: state.moods,
    completedToday,
    toggleHabit,
    addHabit,
    renameHabit,
    updateHabitStyle,
    deleteHabit,
    saveMood,
    clearAll,
    reload: load,
  }
}

