import { useEffect, useRef, useState } from "react"
import type { Habit } from "../types"
import { PALETTE, HABIT_EMOJIS } from "../lib/colors"
import { IconPlus } from "./icons"

interface HabitFormProps {
  habit?: Habit | null
  onSave: (patch: { name: string; emoji: string; color: string }) => void
  onDelete?: (id: string) => void
  onClose: () => void
}

export default function HabitForm({ habit, onSave, onDelete, onClose }: HabitFormProps) {
  const [name, setName] = useState(habit?.name ?? "")
  const [emoji, setEmoji] = useState(habit?.emoji ?? HABIT_EMOJIS[0])
  const [color, setColor] = useState(habit?.color ?? PALETTE[0].value)
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  function submit() {
    const trimmed = name.trim()
    if (!trimmed) return
    onSave({ name: trimmed, emoji, color })
  }

  const title = habit ? "Habit anpassen" : "Neuer Habit"

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center bg-black/40 backdrop-blur-sm animate-fade"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-label={title}
    >
      <div
        className="w-full max-w-md animate-slide-up rounded-t-2xl bg-[var(--surface)] p-6 shadow-[0_-8px_30px_rgba(0,0,0,0.12)]"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="mb-5 flex items-center justify-between">
          <h2 className="text-lg font-semibold tracking-tight">{title}</h2>
          <button
            onClick={onClose}
            aria-label="Schließen"
            className="rounded-lg px-2 py-1 text-[var(--text-muted)] transition-colors hover:bg-[var(--accent-soft)] hover:text-[var(--text)]"
            style={{ minWidth: 44, minHeight: 44 }}
          >
            ✕
          </button>
        </div>

        <div className="mb-5">
          <label className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[var(--text-muted)]">
            Name
          </label>
          <input
            ref={inputRef}
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") submit()
            }}
            placeholder="z. B. Meditieren"
            maxLength={40}
          />
        </div>

        <div className="mb-5">
          <label className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[var(--text-muted)]">
            Symbol
          </label>
          <div className="grid grid-cols-8 gap-2">
            {HABIT_EMOJIS.map((e) => (
              <button
                key={e}
                aria-label={`Symbol ${e}`}
                onClick={() => setEmoji(e)}
                className={`flex h-10 w-10 items-center justify-center rounded-xl text-xl transition-colors ${
                  emoji === e
                    ? "bg-[var(--accent-soft)] text-[var(--text)]"
                    : "text-[var(--text-muted)] hover:bg-[var(--surface-alt)]"
                }`}
                style={{ minHeight: 44 }}
              >
                {e}
              </button>
            ))}
          </div>
        </div>

        <div className="mb-6">
          <label className="mb-1.5 block text-xs font-medium uppercase tracking-wider text-[var(--text-muted)]">
            Farbe
          </label>
          <div className="flex flex-wrap gap-2">
            {PALETTE.map((c) => (
              <button
                key={c.value}
                aria-label={`Farbe ${c.name}`}
                title={c.name}
                onClick={() => setColor(c.value)}
                className="rounded-full transition-transform hover:scale-110"
                style={{
                  width: 32,
                  height: 32,
                  backgroundColor: c.value,
                  boxShadow:
                    color === c.value
                      ? `0 0 0 3px var(--surface), 0 0 0 5px ${c.value}`
                      : "none",
                  minHeight: 32,
                }}
              />
            ))}
          </div>
        </div>

        <div className="flex gap-3">
          {habit && onDelete && (
            <button
              onClick={() => onDelete(habit.id)}
              className="flex h-12 items-center justify-center gap-2 rounded-xl border border-[var(--border-strong)] px-4 text-sm font-medium text-[var(--danger)] transition-colors hover:bg-[var(--danger)] hover:text-white"
              style={{ minWidth: 44 }}
            >
              Löschen
            </button>
          )}
          <button
            onClick={submit}
            disabled={!name.trim()}
            className="flex h-12 flex-1 items-center justify-center gap-2 rounded-xl bg-[var(--accent)] px-4 text-sm font-semibold text-white transition-colors hover:bg-[color-mix(in_srgb,var(--accent)_85%,black)] disabled:cursor-not-allowed disabled:opacity-40"
            style={{ minHeight: 44 }}
          >
            <IconPlus className="h-4 w-4" />
            {habit ? "Speichern" : "Anlegen"}
          </button>
        </div>
      </div>
    </div>
  )
}

import type { Habit } from "../types"
import { IconCheck, IconCheckOutline, IconEdit, IconFlame } from "./icons"

interface HabitRowProps {
  habit: Habit
  completed: boolean
  streak: number
  onToggle: () => void
  onEdit: () => void
  index?: number
}

export default function HabitRow({
  habit,
  completed,
  streak,
  onToggle,
  onEdit,
  index = 0,
}: HabitRowProps) {
  const tint = `rgb(${parseInt(habit.color.slice(1, 3), 16)}, ${parseInt(habit.color.slice(3, 5), 16)}, ${parseInt(habit.color.slice(5, 7), 16)})`

  return (
    <div
      className={`group flex items-center gap-3 rounded-2xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3 transition-colors duration-200 ${
        completed ? "bg-[var(--surface-alt)]" : ""
      }`}
      style={{
        animationDelay: `${index * 60}ms`,
        animation: "fadeIn 0.4s ease both",
      }}
    >
      <button
        onClick={onToggle}
        aria-label={`${completed ? "Entscheiden" : "Erledigen"}: ${habit.name}`}
        aria-pressed={completed}
        className="flex shrink-0 items-center justify-center rounded-full transition-transform duration-200 active:scale-90"
        style={{
          width: 44,
          height: 44,
          color: completed ? "#ffffff" : tint,
          backgroundColor: completed ? tint : "transparent",
          boxShadow: completed ? `0 2px 8px ${tint}` : "none",
        }}
      >
        {completed ? (
          <IconCheck className="h-5 w-5 animate-pop" />
        ) : (
          <IconCheckOutline className="h-5 w-5" />
        )}
      </button>

      <div
        className="text-xl leading-none"
        aria-hidden="true"
        style={{ filter: completed ? "grayscale(0.6) opacity(0.7)" : "none" }}
      >
        {habit.emoji}
      </div>

      <div className="min-w-0 flex-1">
        <div className="flex items-baseline gap-2">
          <span
            className={`truncate text-base font-medium tracking-tight transition-opacity duration-200 ${
              completed ? "opacity-60" : "opacity-100"
            }`}
          >
            {habit.name}
          </span>
          {streak > 0 && (
            <span className="inline-flex items-center gap-0.5 rounded-full px-2 py-0.5 text-xs font-semibold" style={{ backgroundColor: tint, color: "#ffffff" }}>
              <IconFlame className="h-3 w-3" />
              {streak}
            </span>
          )}
        </div>
      </div>

      <button
        onClick={onEdit}
        aria-label={`Habit ${habit.name} bearbeiten`}
        className="flex shrink-0 items-center justify-center rounded-xl p-2 text-[var(--text-muted)] opacity-0 transition-all duration-200 hover:bg-[var(--accent-soft)] hover:text-[var(--text)] group-hover:opacity-100"
        style={{ minHeight: 44, minWidth: 44 }}
      >
        <IconEdit className="h-4 w-4" />
      </button>
    </div>
  )
}

import { useState } from "react"

interface MoodPickerProps {
  value?: number
  note?: string
  onSave: (value: number, note: string) => void
  onClose: () => void
}

const FACES = [
  { value: 1, emoji: "😣", label: "Schlecht" },
  { value: 2, emoji: "😕", label: "Mässig" },
  { value: 3, emoji: "🙂", label: "Okay" },
  { value: 4, emoji: "😄", label: "Gut" },
  { value: 5, emoji: "😊", label: "Sehr gut" },
]

export default function MoodPicker({ value, note, onSave, onClose }: MoodPickerProps) {
  const [picked, setPicked] = useState(value ?? 0)
  const [text, setText] = useState(note ?? "")

  function save() {
    if (!picked) return
    onSave(picked, text.trim())
  }

  return (
    <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-5">
      <div className="mb-4 flex items-center justify-between">
        <h3 className="text-sm font-semibold tracking-tight">Stimmung heute</h3>
        <button
          onClick={onClose}
          aria-label="Schließen"
          className="rounded-lg px-2 py-1 text-[var(--text-muted)] transition-colors hover:bg-[var(--accent-soft)] hover:text-[var(--text)]"
          style={{ minWidth: 44, minHeight: 44 }}
        >
          ✕
        </button>
      </div>

      <div className="mb-5 flex justify-between" role="radiogroup" aria-label="Stimmung">
        {FACES.map((f) => {
          const active = picked === f.value
          return (
            <button
              key={f.value}
              role="radio"
              aria-checked={active}
              aria-label={f.label}
              onClick={() => setPicked(f.value)}
              className="flex flex-col items-center gap-1 transition-transform active:scale-90"
              style={{ minWidth: 44, minHeight: 44 }}
            >
              <span
                className={`text-3xl transition-transform duration-200 ${active ? "scale-115" : "opacity-50"}`}
              >
                {f.emoji}
              </span>
              <span className="text-xs text-[var(--text-muted)]">{f.value}</span>
            </button>
          )
        })}
      </div>

      <div className="mb-4">
        <textarea
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Optionale Notiz…"
          aria-label="Kurznotiz zur Stimmung"
        />
      </div>

      <div className="flex gap-3">
        <button
          onClick={onClose}
          className="flex h-12 flex-1 items-center justify-center rounded-xl border border-[var(--border-strong)] text-sm font-medium transition-colors hover:bg-[var(--accent-soft)]"
          style={{ minHeight: 44 }}
        >
          Abbrechen
        </button>
        <button
          onClick={save}
          disabled={!picked}
          className="flex h-12 flex-1 items-center justify-center rounded-xl bg-[var(--accent)] px-4 text-sm font-semibold text-white transition-colors disabled:cursor-not-allowed disabled:opacity-40"
          style={{ minHeight: 44 }}
        >
          Speichern
        </button>
      </div>
    </div>
  )
}

import { useMemo, useState } from "react"
import { useData } from "../hooks/useData"
import { computeStreaks } from "../lib/streaks"
import { formatGerman, todayKey } from "../lib/date"
import HabitRow from "./HabitRow"
import MoodPicker from "./Mood"
import HabitForm from "./HabitForm"
import EmptyState from "./EmptyState"
import { IconPlus } from "./icons"

export default function Today() {
  const {
    habits,
    completions,
    moods,
    completedToday,
    toggleHabit,
    addHabit,
    renameHabit,
    updateHabitStyle,
    deleteHabit,
    saveMood,
  } = useData()

  const [formHabit, setFormHabit] = useState<{ habit: ReturnType<typeof useData>["habits"][0] | null } | null>(null as any)
  const [moodOpen, setMoodOpen] = useState(false)

  const today = todayKey()
  const dateLabel = formatGerman(new Date())

  const completionsByHabit = useMemo(() => {
    const map = new Map<string, string[]>()
    for (const c of completions) {
      const arr = map.get(c.habitId) ?? []
      arr.push(c.date)
      map.set(c.habitId, arr)
    }
    return map
  }, [completions])

  const streaks = useMemo(() => {
    const map = new Map<string, { current: number; longest: number }>()
    for (const h of habits) {
      map.set(h.id, computeStreaks(completionsByHabit.get(h.id) ?? []))
    }
    return map
  }, [habits, completionsByHabit])

  const doneToday = completedToday.length
  const total = habits.length
  const progress = total === 0 ? 0 : doneToday / total

  const todayMood = moods.find((m) => m.date === today) ?? null

  function openAdd() {
    setFormHabit({ habit: null })
  }

  function openEdit(habit: NonNullable<typeof formHabit["habit"]>) {
    setFormHabit({ habit })
  }

  function handleSave(patch: { name: string; emoji: string; color: string }) {
    if (formHabit?.habit) {
      if (patch.name !== formHabit.habit.name) renameHabit(formHabit.habit.id, patch.name)
      if (patch.emoji !== formHabit.habit.emoji || patch.color !== formHabit.habit.color) {
        updateHabitStyle(formHabit.habit.id, { emoji: patch.emoji, color: patch.color })
      }
    } else {
      addHabit({ name: patch.name, emoji: patch.emoji, color: patch.color })
    }
    setFormHabit(null)
  }

  function handleDelete(id: string) {
    deleteHabit(id)
    setFormHabit(null)
  }

  return (
    <div className="flex flex-col gap-6" id="panel-today" role="tabpanel">
      {/* Header */}
      <header>
        <div className="mb-1 flex items-center gap-2 text-xs font-medium uppercase tracking-widest text-[var(--text-muted)]">
          <IconCalendar />
          {dateLabel}
        </div>
        <div className="mb-3 flex items-end justify-between">
          <h1 className="text-3xl font-bold tracking-tight">
            {doneToday} <span className="text-[var(--text-muted)] text-2xl font-medium">von {total}</span>
          </h1>
          {total > 0 && (
            <span className="text-sm text-[var(--text-muted)]">erledigt</span>
          )}
        </div>
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-[var(--accent-soft)]">
          <div
            className="h-full rounded-full bg-[var(--accent)] transition-[width] duration-500 ease-out"
            style={{ width: `${progress * 100}%` }}
            role="progressbar"
            aria-valuenow={doneToday}
            aria-valuemin={0}
            aria-valuemax={total}
            aria-label={`${doneToday} von ${total} Habits erledigt`}
          />
        </div>
      </header>

      {/* Mood */}
      <section>
        {todayMood ? (
          <div className="flex items-center justify-between rounded-2xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3">
            <div className="flex items-center gap-3">
              <span className="text-2xl">{MOOD_EMOJI(todayMood.value)}</span>
              <div>
                <div className="text-sm font-medium">Stimmung gespeichert</div>
                {todayMood.note && (
                  <div className="text-xs text-[var(--text-muted)]">{todayMood.note}</div>
                )}
              </div>
            </div>
            <button
              onClick={() => setMoodOpen(true)}
              className="rounded-xl px-3 py-2 text-xs font-medium text-[var(--text-muted)] transition-colors hover:bg-[var(--accent-soft)] hover:text-[var(--text)]"
              style={{ minHeight: 44 }}
            >
              Ändern
            </button>
          </div>
        ) : (
          <button
            onClick={() => setMoodOpen(true)}
            className="flex w-full items-center gap-3 rounded-2xl border border-dashed border-[var(--border-strong)] bg-transparent px-4 py-3 text-left text-sm font-medium text-[var(--text-muted)] transition-colors hover:border-[var(--accent)] hover:text-[var(--text)]"
            style={{ minHeight: 56 }}
          >
            <span className="text-xl">🌤</span>
            Stimmung für heute festlegen
          </button>
        )}
      </section>

      {/* Habits */}
      <section>
        {habits.length === 0 ? (
          <EmptyState
            title="Noch keine Habits"
            description="Lege deinen ersten Habit an und starte deine Routine. Kleine Schritte, die Wirkung zeigen."
            action={
              <button
                onClick={openAdd}
                className="inline-flex items-center gap-2 rounded-xl bg-[var(--accent)] px-5 py-3 text-sm font-semibold text-white transition-colors"
                style={{ minHeight: 44 }}
              >
                <IconPlus className="h-4 w-4" />
                Habit anlegen
              </button>
            }
          />
        ) : (
          <div className="flex flex-col gap-2">
