import { useMemo, useState } from "react"
import type { Habit } from "../types"
import { useData } from "../hooks/useData"
import { computeStreaks } from "../lib/streaks"
import { formatGerman, todayKey } from "../lib/date"
import HabitRow from "./HabitRow"
import MoodPicker from "./Mood"
import HabitForm from "./HabitForm"
import EmptyState from "./EmptyState"
import { IconPlus } from "./icons"

type FormState = { habit: Habit | null } | null

const MOOD_EMOJI: Record<number, string> = {
  1: "😣",
  2: "😕",
  3: "🙂",
  4: "😄",
  5: "😊",
}

export default function Today() {
  const {
    habits,
    completions,
    moods,
    completedToday,
    toggleHabit,
    addHabit,
    renameHabit,
    updateHabitStyle,
    deleteHabit,
    saveMood,
  } = useData()

  const [form, setForm] = useState<FormState>(null)
  const [moodOpen, setMoodOpen] = useState(false)

  const dateLabel = formatGerman(new Date())

  const completionsByHabit = useMemo(() => {
    const map = new Map<string, string[]>()
    for (const c of completions) {
      const arr = map.get(c.habitId) ?? []
      arr.push(c.date)
      map.set(c.habitId, arr)
    }
    return map
  }, [completions])

  const streaks = useMemo(() => {
    const map = new Map<string, { current: number; longest: number }>()
    for (const h of habits) {
      map.set(h.id, computeStreaks(completionsByHabit.get(h.id) ?? []))
    }
    return map
  }, [habits, completionsByHabit])

  const doneToday = completedToday.length
  const total = habits.length
  const progress = total === 0 ? 0 : doneToday / total

  const today = todayKey()
  const todayMood = moods.find((m) => m.date === today) ?? null

  function handleSave(patch: { name: string; emoji: string; color: string }) {
    if (form?.habit) {
      if (patch.name !== form.habit.name) renameHabit(form.habit.id, patch.name)
      if (patch.emoji !== form.habit.emoji || patch.color !== form.habit.color) {
        updateHabitStyle(form.habit.id, { emoji: patch.emoji, color: patch.color })
      }
    } else {
      addHabit({ name: patch.name, emoji: patch.emoji, color: patch.color })
    }
    setForm(null)
  }

  return (
    <div className="flex flex-col gap-6" id="panel-today" role="tabpanel">
      {/* Header */}
      <header>
        <div className="mb-1 flex items-center gap-2 text-xs font-medium uppercase tracking-widest text-[var(--text-muted)]">
          {dateLabel}
        </div>
        <div className="mb-3 flex items-end justify-between">
          <h1 className="text-3xl font-bold tracking-tight">
            {doneToday} <span className="text-[var(--text-muted)] text-2xl font-medium">von {total}</span>
          </h1>
          {total > 0 && (
            <span className="text-sm text-[var(--text-muted)]">erledigt</span>
          )}
        </div>
        <div className="h-1.5 w-full overflow-hidden rounded-full bg-[var(--accent-soft)]">
          <div
            className="h-full rounded-full bg-[var(--accent)] transition-[width] duration-500 ease-out"
            style={{ width: `${progress * 100}%` }}
            role="progressbar"
            aria-valuenow={doneToday}
            aria-valuemin={0}
            aria-valuemax={total}
            aria-label={`${doneToday} von ${total} Habits erledigt`}
          />
        </div>
      </header>

      {/* Mood */}
      <section>
        {todayMood ? (
          <div className="flex items-center justify-between rounded-2xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3">
            <div className="flex items-center gap-3">
              <span className="text-2xl" aria-hidden="true">
                {MOOD_EMOJI[todayMood.value] ?? "🙂"}
              </span>
              <div>
                <div className="text-sm font-medium">Stimmung gespeichert</div>
                {todayMood.note && (
                  <div className="text-xs text-[var(--text-muted)]">{todayMood.note}</div>
                )}
              </div>
            </div>
            <button
              onClick={() => setMoodOpen(true)}
              className="rounded-xl px-3 py-2 text-xs font-medium text-[var(--text-muted)] transition-colors hover:bg-[var(--accent-soft)] hover:text-[var(--text)]"
              style={{ minHeight: 44 }}
            >
              Ändern
            </button>
          </div>
        ) : (
          <button
            onClick={() => setMoodOpen(true)}
            className="flex w-full items-center gap-3 rounded-2xl border border-dashed border-[var(--border-strong)] bg-transparent px-4 py-3 text-left text-sm font-medium text-[var(--text-muted)] transition-colors hover:border-[var(--accent)] hover:text-[var(--text)]"
            style={{ minHeight: 56 }}
          >
            <span className="text-xl" aria-hidden="true">
              🌤
            </span>
            Stimmung für heute festlegen
          </button>
        )}
      </section>

      {/* Habits */}
      <section>
        {habits.length === 0 ? (
          <EmptyState
            title="Noch keine Habits"
            description="Lege deinen ersten Habit an und starte deine Routine. Kleine Schritte, die Wirkung zeigen."
            action={
              <button
                onClick={() => setForm({ habit: null })}
                className="inline-flex items-center gap-2 rounded-xl bg-[var(--accent)] px-5 py-3 text-sm font-semibold text-white transition-colors"
                style={{ minHeight: 44 }}
              >
                <IconPlus className="h-4 w-4" />
                Habit anlegen
              </button>
            }
          />
        ) : (
          <div className="flex flex-col gap-2">
            {habits.map((habit, i) => (
              <HabitRow
                key={habit.id}
                habit={habit}
                completed={completedToday.includes(habit.id)}
                streak={streaks.get(habit.id)?.current ?? 0}
                onToggle={() => toggleHabit(habit.id)}
                onEdit={() => setForm({ habit })}
                index={i}
              />
            ))}
          </div>
        )}

        {habits.length > 0 && (
          <button
            onClick={() => setForm({ habit: null })}
            className="mt-3 flex items-center justify-center gap-2 rounded-2xl border border-[var(--border)] bg-[var(--surface)] px-4 py-3 text-sm font-medium text-[var(--text-muted)] transition-colors hover:border-[var(--accent)] hover:text-[var(--text)]"
            style={{ minHeight: 48 }}
          >
            <IconPlus className="h-4 w-4" />
            Weiteren Habit hinzufügen
          </button>
        )}
      </section>

      {form && (
        <HabitForm
          habit={form.habit}
          onSave={handleSave}
          onDelete={(id) => {
            deleteHabit(id)
            setForm(null)
          }}
          onClose={() => setForm(null)}
        />
      )}

      {moodOpen && (
        <MoodPicker
          value={todayMood?.value}
          note={todayMood?.note}
          onSave={(value, note) => {
            saveMood(value, note)
            setMoodOpen(false)
          }}
          onClose={() => setMoodOpen(false)}
        />
      )}
    </div>
  )
}

import { useMemo } from "react"
import {
  BarChart,
  Bar,
  LineChart,
  Line,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  ResponsiveContainer,
} from "recharts"
import { useData } from "../hooks/useData"
import { useDarkMode } from "../hooks/useDarkMode"
import { addDaysKey, weekdayShort } from "../lib/date"
import EmptyState from "./EmptyState"
import { IconChart } from "./icons"

export default function Week() {
  const { completions, moods } = useData()
  const { appearance } = useDarkMode()
  const isDark =
    appearance === "dark" ||
    (appearance === "system" &&
      typeof window !== "undefined" &&
      window.matchMedia("(prefers-color-scheme: dark)").matches)

  const accent = isDark ? "#f5f5f0" : "#111111"
  const muted = isDark ? "#9a9a96" : "#787774"
  const success = isDark ? "#6fbf7b" : "#3a7d44"

  const days = useMemo(() => {
    const keys: string[] = []
    for (let i = 6; i >= 0; i--) keys.push(addDaysKey(new Date().toISOString().slice(0, 10).replace(/-/g, "/"), -i))
    return keys
  }, [])

  // Compute ISO-ish keys robustly via helper instead:
  const keys = useMemo(() => {
    const out: string[] = []
    const now = new Date()
    for (let i = 6; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i)
      const y = d.getFullYear()
      const m = String(d.getMonth() + 1).padStart(2, "0")
      const day = String(d.getDate()).padStart(2, "0")
      out.push(`${y}-${m}-${day}`)
    }
    return out
  }, [])

  const completedByDay = useMemo(() => {
    const set = new Set(completions.map((c) => `${c.habitId}::${c.date}`))
    const counts = new Map<string, number>()
    for (const key of keys) counts.set(key, 0)
    for (const c of completions) {
      if (set.has(`${c.habitId}::${c.date}`)) {
        counts.set(c.date, (counts.get(c.date) ?? 0) + 1)
      }
    }
    return counts
  }, [completions, keys])

  const moodByDay = useMemo(() => {
    const map = new Map<string, number>()
    for (const m of moods) map.set(m.date, m.value)
    return map
  }, [moods])

  const chartData = keys.map((key) => ({
    day: weekdayShort(key),
    done: completedByDay.get(key) ?? 0,
    mood: moodByDay.get(key) ?? 0,
  }))

  const anyData = chartData.some((d) => d.done > 0) || moods.length > 0

  function MoodTooltip({ active, payload }: any) {
    if (!active || !payload || payload.length === 0) return null
    return (
      <div className="rounded-lg border border-[var(--border)] bg-[var(--surface)] px-3 py-2 text-xs shadow-sm">
        <div className="font-medium">Stimmung</div>
        <div style={{ color: success }}>
          {"😀".repeat(payload[0].value)}
        </div>
      </div>
    )
  }

  return (
    <div className="flex flex-col gap-6" id="panel-week" role="tabpanel">
      <header>
        <h1 className="text-2xl font-bold tracking-tight">Woche</h1>
        <p className="mt-1 text-sm text-[var(--text-muted)]">Letzte 7 Tage</p>
      </header>

      {!anyData ? (
        <EmptyState
          title="Noch keine Daten"
          description="Erledige in den nächsten Tagen deine Habits und trage deine Stimmung ein. Die Woche füllt sich dann hier."
          icon={<IconChart className="h-10 w-10" />}
        />
      ) : (
        <div className="flex flex-col gap-6">
          <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
            <h2 className="mb-3 text-sm font-semibold tracking-tight">
              Erledigte Habits pro Tag
            </h2>
            <div className="h-40">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} margin={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                  <CartesianGrid stroke="var(--border)" strokeDasharray="3 3" vertical={false} />
                  <XAxis
                    dataKey="day"
                    axisLine={false}
                    tickLine={false}
                    tick={{ fill: muted, fontSize: 12 }}
                  />
                  <YAxis
                    axisLine={false}
                    tickLine={false}
                    tick={{ fill: muted, fontSize: 12 }}
                    allowDecimals={false}
                  />
                  <Tooltip
                    contentStyle={{
                      borderRadius: 8,
                      border: "1px solid var(--border)",
                      background: "var(--surface)",
                      fontSize: 12,
                      color: "var(--text)",
                    }}
                    formatter={(value: number) => [`${value} erledigt`, "Habits"]}
                  />
                  <Bar dataKey="done" fill={accent} radius={[6, 6, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-4">
            <h2 className="mb-3 text-sm font-semibold tracking-tight">Stimmungsverlauf</h2>
            <div className="h-40">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData} margin={{ top: 8, right: 8, bottom: 8, left: 8 }}>
                  <CartesianGrid stroke="var(--border)" strokeDasharray="3 3" vertical={false} />
                  <XAxis
                    dataKey="day"
                    axisLine={false}
                    tickLine={false}
                    tick={{ fill: muted, fontSize: 12 }}
                  />
                  <YAxis
                    domain={[1, 5]}
                    axisLine={false}
                    tickLine={false}
                    tick={{ fill: muted, fontSize: 12 }}
                    ticks={[1, 2, 3, 4, 5]}
                  />
                  <Tooltip content={<MoodTooltip />} />
                  <Line
                    type="monotone"
                    dataKey="mood"
                    stroke={success}
                    strokeWidth={2.5}
                    dot={{ r: 4, fill: success, strokeWidth: 0 }}
                    activeDot={{ r: 6 }}
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

