      <section>
        <h2 className="mb-2 text-xs font-medium uppercase tracking-wider text-[var(--text-muted)]">
          Erscheinungsbild
        </h2>
        <div className="flex flex-col gap-2">
          {APPEARANCE_OPTIONS.map(({ id, label, icon: Icon }) => {
